===== FILE: index.html =====
<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>畅行旅行 - 国内旅行预订平台</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif; color: #333; background: #f8f9fc; line-height: 1.6; }
        a { text-decoration: none; color: inherit; }
        .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

        /* Header */
        .header { background: #fff; border-bottom: 1px solid #e8ecf1; position: sticky; top: 0; z-index: 100; }
        .header-inner { display: flex; align-items: center; justify-content: space-between; height: 68px; }
        .logo { display: flex; align-items: center; gap: 10px; font-size: 22px; font-weight: 700; color: #1a56db; }
        .logo-icon { width: 36px; height: 36px; background: linear-gradient(135deg, #1a56db, #3b82f6); border-radius: 8px; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 18px; font-weight: 800; }
        .nav { display: flex; align-items: center; gap: 32px; }
        .nav a { font-size: 15px; color: #555; font-weight: 500; transition: color 0.2s; }
        .nav a:hover { color: #1a56db; }
        .nav-btn { background: #1a56db; color: #fff !important; padding: 10px 22px; border-radius: 8px; font-size: 14px; font-weight: 600; transition: background 0.2s; }
        .nav-btn:hover { background: #1648b8; }

        /* Hero */
        .hero { background: linear-gradient(135deg, #0f172a 0%, #1e3a5f 50%, #1a56db 100%); padding: 80px 0 100px; position: relative; overflow: hidden; }
        .hero::before { content: ''; position: absolute; top: -50%; right: -20%; width: 600px; height: 600px; background: radial-gradient(circle, rgba(59,130,246,0.15) 0%, transparent 70%); border-radius: 50%; }
        .hero::after { content: ''; position: absolute; bottom: -30%; left: -10%; width: 400px; height: 400px; background: radial-gradient(circle, rgba(96,165,250,0.1) 0%, transparent 70%); border-radius: 50%; }
        .hero-content { position: relative; z-index: 1; text-align: center; }
        .hero h1 { font-size: 42px; color: #fff; font-weight: 800; margin-bottom: 16px; letter-spacing: -0.5px; }
        .hero p { font-size: 18px; color: rgba(255,255,255,0.8); margin-bottom: 48px; }
        .search-box { background: #fff; border-radius: 16px; padding: 28px; max-width: 900px; margin: 0 auto; box-shadow: 0 20px 60px rgba(0,0,0,0.2); }
        .search-row { display: flex; gap: 16px; flex-wrap: wrap; }
        .search-field { flex: 1; min-width: 180px; }
        .search-field label { display: block; font-size: 13px; color: #888; margin-bottom: 6px; font-weight: 500; }
        .search-field input, .search-field select { width: 100%; padding: 14px 16px; border: 1.5px solid #e2e8f0; border-radius: 10px; font-size: 15px; color: #333; outline: none; transition: border-color 0.2s; background: #f8fafc; }
        .search-field input:focus, .search-field select:focus { border-color: #3b82f6; background: #fff; }
        .search-btn { background: linear-gradient(135deg, #1a56db, #3b82f6); color: #fff; border: none; padding: 14px 40px; border-radius: 10px; font-size: 16px; font-weight: 600; cursor: pointer; transition: transform 0.2s, box-shadow 0.2s; align-self: flex-end; height: 50px; }
        .search-btn:hover { transform: translateY(-1px); box-shadow: 0 8px 24px rgba(26,86,219,0.35); }

        /* Quick Stats */
        .stats { display: flex; justify-content: center; gap: 60px; padding: 48px 0; }
        .stat-item { text-align: center; }
        .stat-num { font-size: 32px; font-weight: 800; color: #1a56db; }
        .stat-label { font-size: 14px; color: #777; margin-top: 4px; }

        /* Popular Destinations */
        .section { padding: 72px 0; }
        .section-title { font-size: 30px; font-weight: 700; margin-bottom: 8px; text-align: center; }
        .section-sub { font-size: 15px; color: #888; text-align: center; margin-bottom: 48px; }
        .dest-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
        .dest-card { border-radius: 14px; overflow: hidden; background: #fff; box-shadow: 0 2px 12px rgba(0,0,0,0.06); transition: transform 0.3s, box-shadow 0.3s; cursor: pointer; }
        .dest-card:hover { transform: translateY(-4px); box-shadow: 0 12px 32px rgba(0,0,0,0.1); }
        .dest-img { height: 180px; position: relative; }
        .dest-img-1 { background: linear-gradient(135deg, #f97316, #fbbf24); }
        .dest-img-2 { background: linear-gradient(135deg, #0ea5e9, #38bdf8); }
        .dest-img-3 { background: linear-gradient(135deg, #10b981, #34d399); }
        .dest-img-4 { background: linear-gradient(135deg, #8b5cf6, #a78bfa); }
        .dest-img-label { position: absolute; bottom: 12px; left: 12px; background: rgba(0,0,0,0.6); color: #fff; padding: 4px 12px; border-radius: 6px; font-size: 12px; }
        .dest-info { padding: 18px; }
        .dest-info h3 { font-size: 17px; font-weight: 600; margin-bottom: 6px; }
        .dest-info p { font-size: 13px; color: #888; }
        .dest-price { margin-top: 10px; font-size: 15px; color: #1a56db; font-weight: 700; }

        /* Services */
        .services-bg { background: #fff; }
        .services-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
        .service-card { text-align: center; padding: 36px 20px; border-radius: 14px; background: #f8fafc; transition: background 0.2s; }
        .service-card:hover { background: #eff6ff; }
        .service-icon { width: 56px; height: 56px; margin: 0 auto 16px; background: linear-gradient(135deg, #dbeafe, #bfdbfe); border-radius: 14px; display: flex; align-items: center; justify-content: center; font-size: 24px; }
        .service-card h4 { font-size: 16px; font-weight: 600; margin-bottom: 8px; }
        .service-card p { font-size: 13px; color: #777; line-height: 1.5; }

        /* CTA */
        .cta { background: linear-gradient(135deg, #1a56db, #3b82f6); border-radius: 20px; padding: 56px; text-align: center; margin: 0 24px; }
        .cta h2 { color: #fff; font-size: 28px; font-weight: 700; margin-bottom: 12px; }
        .cta p { color: rgba(255,255,255,0.85); font-size: 15px; margin-bottom: 28px; }
        .cta-btn { background: #fff; color: #1a56db; padding: 14px 36px; border-radius: 10px; font-size: 16px; font-weight: 600; display: inline-block; transition: transform 0.2s; }
        .cta-btn:hover { transform: translateY(-2px); }

        /* Footer */
        .footer { background: #1e293b; color: #94a3b8; padding: 56px 0 32px; margin-top: 72px; }
        .footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 48px; margin-bottom: 40px; }
        .footer h4 { color: #fff; font-size: 15px; font-weight: 600; margin-bottom: 16px; }
        .footer a { display: block; font-size: 14px; margin-bottom: 10px; color: #94a3b8; transition: color 0.2s; }
        .footer a:hover { color: #e2e8f0; }
        .footer-desc { font-size: 14px; line-height: 1.8; margin-top: 12px; }
        .footer-bottom { border-top: 1px solid #334155; padding-top: 24px; font-size: 13px; text-align: center; }

        @media (max-width: 900px) {
            .dest-grid { grid-template-columns: repeat(2, 1fr); }
            .services-grid { grid-template-columns: repeat(2, 1fr); }
            .footer-grid { grid-template-columns: 1fr 1fr; }
            .hero h1 { font-size: 30px; }
            .stats { gap: 30px; flex-wrap: wrap; }
        }
        @media (max-width: 600px) {
            .dest-grid { grid-template-columns: 1fr; }
            .services-grid { grid-template-columns: 1fr; }
            .search-row { flex-direction: column; }
            .search-btn { width: 100%; }
            .nav { gap: 16px; }
            .nav a:not(.nav-btn) { display: none; }
        }
    </style>
</head>
<body>
