<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>酒店搜索结果 - 三亚 - 畅行旅行</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif; color: #333; background: #f8f9fc; line-height: 1.6; }
        a { text-decoration: none; color: inherit; }
        .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

        .header { background: #fff; border-bottom: 1px solid #e8ecf1; position: sticky; top: 0; z-index: 100; }
        .header-inner { display: flex; align-items: center; justify-content: space-between; height: 68px; }
        .logo { display: flex; align-items: center; gap: 10px; font-size: 22px; font-weight: 700; color: #1a56db; }
        .logo-icon { width: 36px; height: 36px; background: linear-gradient(135deg, #1a56db, #3b82f6); border-radius: 8px; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 18px; font-weight: 800; }
        .nav { display: flex; align-items: center; gap: 32px; }
        .nav a { font-size: 15px; color: #555; font-weight: 500; transition: color 0.2s; }
        .nav a:hover { color: #1a56db; }
        .nav-btn { background: #1a56db; color: #fff !important; padding: 10px 22px; border-radius: 8px; font-size: 14px; font-weight: 600; }
        .nav-btn:hover { background: #1648b8; }

        /* Search Bar */
        .search-bar { background: #fff; border-bottom: 1px solid #e8ecf1; padding: 20px 0; }
        .search-bar-inner { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; }
        .search-tag { display: flex; align-items: center; gap: 8px; background: #eff6ff; color: #1a56db; padding: 10px 18px; border-radius: 8px; font-size: 14px; font-weight: 500; }
        .search-tag-icon { font-size: 16px; }
        .search-bar-btn { margin-left: auto; background: #1a56db; color: #fff; border: none; padding: 10px 24px; border-radius: 8px; font-size: 14px; font-weight: 600; cursor: pointer; }
        .search-bar-btn:hover { background: #1648b8; }

        /* Main Layout */
        .main-layout { display: grid; grid-template-columns: 280px 1fr; gap: 28px; padding: 32px 0; }

        /* Filters */
        .filters { background: #fff; border-radius: 14px; padding: 24px; height: fit-content; box-shadow: 0 1px 8px rgba(0,0,0,0.04); }
        .filter-title { font-size: 16px; font-weight: 700; margin-bottom: 20px; }
        .filter-group { margin-bottom: 24px; }
        .filter-group h4 { font-size: 13px; color: #888; font-weight: 600; margin-bottom: 12px; text-transform: uppercase; letter-spacing: 0.5px; }
        .filter-option { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; cursor: pointer; }
        .filter-option input[type="checkbox"] { width: 18px; height: 18px; accent-color: #1a56db; cursor: pointer; }
        .filter-option label { font-size: 14px; color: #555; cursor: pointer; }
        .filter-option .count { margin-left: auto; font-size: 12px; color: #aaa; }
        .filter-divider { border: none; border-top: 1px solid #f0f0f0; margin: 20px 0; }
        .price-range { display: flex; align-items: center; gap: 8px; margin-top: 8px; }
        .price-range input { width: 80px; padding: 8px 10px; border: 1px solid #e2e8f0; border-radius: 6px; font-size: 13px; }
        .filter-reset { width: 100%; padding: 12px; background: #f1f5f9; border: none; border-radius: 8px; font-size: 14px; color: #555; cursor: pointer; margin-top: 16px; font-weight: 500; }
        .filter-reset:hover { background: #e2e8f0; }

        /* Results */
        .results-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px; }
        .results-count { font-size: 15px; color: #666; }
        .results-count strong { color: #333; }
        .results-sort { display: flex; align-items: center; gap: 8px; }
        .results-sort select { padding: 8px 12px; border: 1px solid #e2e8f0; border-radius: 8px; font-size: 13px; color: #555; background: #fff; }

        .hotel-card { display: flex; background: #fff; border-radius: 14px; overflow: hidden; margin-bottom: 20px; box-shadow: 0 1px 8px rgba(0,0,0,0.04); transition: box-shadow 0.3s, transform 0.2s; cursor: pointer; }
        .hotel-card:hover { box-shadow: 0 8px 28px rgba(0,0,0,0.1); transform: translateY(-2px); }
        .hotel-img { width: 280px; min-height: 220px; flex-shrink: 0; position: relative; }
        .hotel-img-1 { background: linear-gradient(135deg, #0ea5e9, #67e8f9); }
        .hotel-img-2 { background: linear-gradient(135deg, #f59e0b, #fde68a); }
        .hotel-img-3 { background: linear-gradient(135deg, #10b981, #6ee7b7); }
        .hotel-img-4 { background: linear-gradient(135deg, #8b5cf6, #c4b5fd); }
        .hotel-img-5 { background: linear-gradient(135deg, #ef4444, #fca5a5); }
        .hotel-badge { position: absolute; top: 12px; left: 12px; background: rgba(0,0,0,0.6); color: #fff; padding: 4px 10px; border-radius: 5px; font-size: 11px; font-weight: 600; }
        .hotel-info { padding: 24px; flex: 1; display: flex; flex-direction: column; }
        .hotel-info-top { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 8px; }
        .hotel-name { font-size: 19px; font-weight: 700; color: #1a202c; }
        .hotel-rating { display: flex; align-items: center; gap: 6px; }
        .rating-score { font-size: 16px; font-weight: 700; color: #f59e0b; }
        .rating-text { font-size: 13px; color: #f59e0b; }
        .hotel-addr { font-size: 13px; color: #888; margin-bottom: 12px; }
        .hotel-tags { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 14px; }
        .hotel-tag { background: #f0fdf4; color: #16a34a; padding: 4px 10px; border-radius: 5px; font-size: 12px; font-weight: 500; }
        .hotel-tag-blue { background: #eff6ff; color: #2563eb; }
        .hotel-tag-orange { background: #fff7ed; color: #ea580c; }
        .hotel-desc { font-size: 13px; color: #777; line-height: 1.6; margin-bottom: 16px; flex: 1; }
        .hotel-bottom { display: flex; align-items: center; justify-content: space-between; padding-top: 16px; border-top: 1px solid #f1f5f9; }
